import{_ as o,o as t,c as i,a5 as r}from"./chunks/framework.D8mhuL_-.js";const u=JSON.parse('{"title":"Service scopes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/app/service-scopes.md","filePath":"guide/app/service-scopes.md"}'),a={name:"guide/app/service-scopes.md"};function c(s,e,n,l,d,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="service-scopes" tabindex="-1">Service scopes <a class="header-anchor" href="#service-scopes" aria-label="Permalink to &quot;Service scopes&quot;">​</a></h1><p><code>scope</code> decides who owns a <code>craftService</code> instance and how its factory receives configuration.</p><div class="tip custom-block"><p class="custom-block-title">Short version</p><p>Use <code>toProvide</code> for state or context owned by a component, feature, or route, even when only one component currently consumes it. Use <code>function</code> for reusable logic called by other services when each call should get its own inputs and service context. Use <code>global</code> only for an app-wide singleton.</p></div><h2 id="supported-scopes" tabindex="-1">Supported Scopes <a class="header-anchor" href="#supported-scopes" aria-label="Permalink to &quot;Supported Scopes&quot;">​</a></h2><h3 id="global" tabindex="-1"><code>global</code> <a class="header-anchor" href="#global" aria-label="Permalink to &quot;`global`&quot;">​</a></h3><ul><li>singleton provided at root</li><li>factory runs when the service is first resolved, unless <code>appStart: true</code> makes it eager</li><li>ideal for app-wide services and shared state</li><li>no explicit <code>provideX()</code> helper</li><li>has no factory inputs, including <code>$provided</code></li></ul><h3 id="toprovide" tabindex="-1"><code>toProvide</code> <a class="header-anchor" href="#toprovide" aria-label="Permalink to &quot;`toProvide`&quot;">​</a></h3><ul><li>one instance per provider scope, created when its token is first resolved</li><li>use for mutable state or context owned by a component, feature, or route</li><li>configure it with <code>provideX()</code> where that owner is mounted</li><li>works well with tests that need explicit providers</li><li>accepts only <code>$provided</code> factory configuration; use <code>withComponentProviders</code> when those values come from component inputs</li></ul><h3 id="manuallyprovidedatroot" tabindex="-1"><code>manuallyProvidedAtRoot</code> <a class="header-anchor" href="#manuallyprovidedatroot" aria-label="Permalink to &quot;`manuallyProvidedAtRoot`&quot;">​</a></h3><ul><li>explicit provider helper, but designed to be mounted at root</li><li>exposes the generated <code>provideX()</code> helper for explicit root composition</li><li>allows this scope to be yielded by global services, which is not possible with <code>toProvide</code> (it still requires explicit setup when testing with <code>setupCraftServiceTestingByRegister</code>)</li><li>accepts only <code>$provided</code> factory configuration, supplied to <code>provideX()</code></li></ul><h3 id="function" tabindex="-1"><code>function</code> <a class="header-anchor" href="#function" aria-label="Permalink to &quot;`function`&quot;">​</a></h3><ul><li>creates a fresh service context on each <code>X(...)</code> helper call; no injector provider or shared cached instance</li><li>useful for reusable operations called by other services, such as a query helper that gets different parameters on each call</li><li>accepts call-site inputs only; pass every value directly to <code>X(...)</code></li></ul><h3 id="abstract" tabindex="-1"><code>abstract</code> <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;`abstract`&quot;">​</a></h3><ul><li>declares a contract without implementation</li><li>exposes a requirement token to force a concrete implementation later</li></ul><h2 id="recommendations-for-choosing-a-scope" tabindex="-1">Recommendations For Choosing a Scope <a class="header-anchor" href="#recommendations-for-choosing-a-scope" aria-label="Permalink to &quot;Recommendations For Choosing a Scope&quot;">​</a></h2><p><code>provideX()</code> registers a provider; it does not eagerly run the service factory. The instance is created and cached in that injector the first time <code>X()</code> is resolved. <code>appStart: true</code> makes the service eager during app initialization.</p><ul><li>Use <code>toProvide</code> for state that belongs to a component or route, even if the owning component is its only consumer. Put <code>provideX()</code> in that component&#39;s or route&#39;s providers. If configuration comes from component inputs, pass it once with <code>withComponentProviders</code>; consumers then call <code>X()</code> without repeating those values.</li><li>Use <code>function</code> for reusable per-call work composed by other services. Each <code>X(inputs)</code> call creates its own service context, so it is not a shared store for a component&#39;s state.</li><li>Be careful with <code>toProvide</code>: a missing provider is a runtime failure unless the route DI check is armed. The <a href="/craft/guide/routing/setup.html">route DI check</a> and <a href="/craft/guide/testing/architecture.html#assertroutediproofs">architecture tests</a> keep that proof in place.</li><li>Use <code>global</code> when the instance is intentionally shared application-wide.</li><li>Use <code>manuallyProvidedAtRoot</code> only when an explicit root provider is needed, including when a global service must depend on a configured provider.</li><li>Use <code>abstract</code> when the implementation should be chosen by the mounting site.</li><li>For startup-only logic that should run when the app boots but is not injected elsewhere, prefer <code>function</code> together with <code>provideAppInitializer(...)</code>. If the same instance also needs to be injected by other services, use <code>global</code> instead.</li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/craft/guide/app/craft-service.html">craftService</a></li><li><a href="/craft/guide/routing/route-providers.html">Route providers</a> — providing a service from a route</li><li><a href="/craft/guide/testing/services.html">Testing services</a></li></ul>',19)])])}const f=o(a,[["render",c]]);export{u as __pageData,f as default};
